/**
 * 檔案用途：逐一驗證工作區四個 repo 與共用 harness 副本，防止規則漂移。
 * 所在層：工作區 scripts；只讀明確清單，不遞迴掃描憑證或文章內容。
 * 主要關聯：workspace-harness.json、各 repo scripts/check-harness.mjs。
 */
import { readFileSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const config = JSON.parse(readFileSync(resolve(root, 'workspace-harness.json'), 'utf8'));
let failed = false;
for (const repo of config.repositories) {
  const cwd = resolve(root, repo);
  console.log(`Checking ${repo}`);
  const result = spawnSync(process.execPath, ['scripts/check-harness.mjs'], { cwd, stdio: 'inherit' });
  if (result.error || result.status !== 0) failed = true;
}
for (const name of config.sharedFiles) {
  try {
    const canonical = readFileSync(resolve(root, config.repositories[0], name));
    for (const repo of config.repositories.slice(1)) {
      // 為什麼比對內容：各 repo 必須能獨立 clone，因此不以跨 repo symlink 共用正本。
      if (!canonical.equals(readFileSync(resolve(root, repo, name)))) {
        console.error(`${repo}/${name}: shared harness drift`);
        failed = true;
      }
    }
  } catch {
    console.error(`${name}: shared harness file missing`);
    failed = true;
  }
}
if (failed) process.exitCode = 1;
else console.log(`Workspace harness passed: ${config.repositories.length} repositories, ${config.sharedFiles.length} shared files.`);
